preConditionHook:
// EL: bullStrongBodies = CountIF(close > open and
//     close - open >= strongBodyFraction * (high - low), windowBars),
// and the mirror on bear bodies for the short side.
// CountIF counts bars 0..N-1 INCLUDING the current bar and the counted
// condition is a true SERIES (EL_FEATURES `countif`, VERIFIED) -- every price
// term inside it shifts with the counted bar, which is what this loop does.
// The counted condition is on PRICES, which have real history back to the
// chart start, so no zero-filled variable mirror is needed; the same
// arrangement OppositeBodyCountInWindow uses.
// A tie bar (close == open within the EL tolerance) counts for neither side.
// Products, not quotients: EasyLanguage raises a runtime divide-by-zero error
// on a zero denominator and a zero-range bar is legal data.
// The counts are EL numeric variables, so they are doubles here and the
// threshold comparison is an ordinary EL relational. They persist across bars,
// so both are reset before the loop.
bullStrongBodies = 0.0;
bearStrongBodies = 0.0;
for (int i = 0; i < (int)windowBars; ++i) {
    if (el_gt(close[i], open[i])
        && el_ge(close[i] - open[i], strongBodyFraction * (high[i] - low[i]))) {
        bullStrongBodies = bullStrongBodies + 1;
    }
    if (el_lt(close[i], open[i])
        && el_ge(open[i] - close[i], strongBodyFraction * (high[i] - low[i]))) {
        bearStrongBodies = bearStrongBodies + 1;
    }
}
